MERGE fact_sales_order_dtl_copy1 AS target USING (VALUES
(#{row.BP}, #{row.F_SALESID}, #{row.F_DOCDATE}, /* ... */)
) AS src(BP, F_SALESID, F_DOCDATE /* ... */) ON target.BP = src.BP AND target.F_SALESID = src.F_SALESID AND target.F_ITEMID=src.F_ITEMID WHEN MATCHED THEN UPDATE SET F_DOCDATE = src.F_DOCDATE /* ... */ WHEN NOT MATCHED THEN INSERT (BP, F_SALESID, F_DOCDATE /* ... */) VALUES (src.BP, src.F_SALESID, src.F_DOCDATE /* ... */);

mapper.delete:
DELETE FROM fact_sales_order_dtl_copy1
WHERE BP = #{BP} AND F_SALESID IN
#{id}
